"use strict";(self.webpackChunkosgiliath_kb=self.webpackChunkosgiliath_kb||[]).push([["2753"],{9433(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>h,frontMatter:()=>r,contentTitle:()=>o,toc:()=>c,assets:()=>l});var a=JSON.parse('{"id":"explanations/aimachinelearning/agentarchitecture/explanation-reconciling-agent-plans-with-completed-temporal-activities","title":"Reconciling AI Decisions With Completed Temporal Activities \u2014 Plan Is Intent, History Is Fact","description":"An AI agent rarely follows a long plan exactly as first proposed. Tool results expose missing facts, external systems change, policies arrive through human input, and a model may discover that an earlier assumption was wrong. ReAct-style agents were explicitly designed around this interleaving of reasoning, action, observation, and plan updates rather than one immutable plan. The engineering difficulty begins when those actions are durable side effects.","source":"@site/docs/explanations/aimachinelearning/agentarchitecture/explanation-reconciling-agent-plans-with-completed-temporal-activities.md","sourceDirName":"explanations/aimachinelearning/agentarchitecture","slug":"/explanations/aimachinelearning/agentarchitecture/explanation-reconciling-agent-plans-with-completed-temporal-activities","permalink":"/kb/explanations/aimachinelearning/agentarchitecture/explanation-reconciling-agent-plans-with-completed-temporal-activities","draft":false,"unlisted":false,"editUrl":"https://github.com/OsgiliathEnterprise/kb/blob/main/docs/explanations/aimachinelearning/agentarchitecture/explanation-reconciling-agent-plans-with-completed-temporal-activities.md","tags":[],"version":"current","lastUpdatedAt":1790698044000,"frontMatter":{"title":"Reconciling AI Decisions With Completed Temporal Activities \u2014 Plan Is Intent, History Is Fact","diataxis":"Explanation","domain":"ai-machine-learning","topic":"agent-architecture","source":"DZone AI/ML","source_url":"https://dzone.com/articles/agent-plan-temporal-activities","date":"2026-09-29T00:00:00.000Z","keywords":["knowledge-base","agent-architecture","ai-machine-learning","explanations"]},"sidebar":"main","previous":{"title":"Progressive Disclosure for AI Agents: On-Demand Skills Instead of Giant Prompts","permalink":"/kb/explanations/aimachinelearning/agentarchitecture/explanation-progressive-disclosure-on-demand-skills"},"next":{"title":"Sandboxed Execution and Runtime Engineering: What BoxAgnts Teaches About Agent Infrastructure","permalink":"/kb/explanations/aimachinelearning/agentarchitecture/explanation-sandboxed-execution-runtime-engineering-for-ai-agents"}}'),i=t(4848),s=t(8453);let r={title:"Reconciling AI Decisions With Completed Temporal Activities \u2014 Plan Is Intent, History Is Fact",diataxis:"Explanation",domain:"ai-machine-learning",topic:"agent-architecture",source:"DZone AI/ML",source_url:"https://dzone.com/articles/agent-plan-temporal-activities",date:new Date("2026-09-29T00:00:00.000Z"),keywords:["knowledge-base","agent-architecture","ai-machine-learning","explanations"]},o="Reconciling AI Decisions With Completed Temporal Activities \u2014 Plan Is Intent, History Is Fact",l={},c=[{value:"A plan is intent; history is fact",id:"a-plan-is-intent-history-is-fact",level:2},{value:"Replanning should consume effects, not merely step status",id:"replanning-should-consume-effects-not-merely-step-status",level:2},{value:"Two guards: planning epochs and stable operation identity",id:"two-guards-planning-epochs-and-stable-operation-identity",level:2},{value:"Cancellation and compensation are forward actions",id:"cancellation-and-compensation-are-forward-actions",level:2},{value:"Durable agents need forward-only semantics",id:"durable-agents-need-forward-only-semantics",level:2},{value:"The central design rule",id:"the-central-design-rule",level:2},{value:"Related notes",id:"related-notes",level:2},{value:"References",id:"references",level:2}];function d(e){let n={a:"a",blockquote:"blockquote",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"reconciling-ai-decisions-with-completed-temporal-activities--plan-is-intent-history-is-fact",children:"Reconciling AI Decisions With Completed Temporal Activities \u2014 Plan Is Intent, History Is Fact"})}),"\n",(0,i.jsxs)(n.p,{children:["An AI agent rarely follows a long plan exactly as first proposed. Tool results expose missing facts, external systems change, policies arrive through human input, and a model may discover that an earlier assumption was wrong. ReAct-style agents were explicitly designed around this interleaving of reasoning, action, observation, and plan updates rather than one immutable plan. The engineering difficulty begins when those actions are ",(0,i.jsx)(n.strong,{children:"durable side effects"}),"."]}),"\n",(0,i.jsx)(n.p,{children:"In Temporal, a completed Activity is not an intention that can be edited out of a revised plan; its completion and result are part of the Workflow Event History. Replanning therefore has to reconcile a new decision with an already-real past."}),"\n",(0,i.jsx)(n.h2,{id:"a-plan-is-intent-history-is-fact",children:"A plan is intent; history is fact"}),"\n",(0,i.jsxs)(n.p,{children:["The cleanest mental model separates ",(0,i.jsx)(n.strong,{children:"plan state"})," from ",(0,i.jsx)(n.strong,{children:"committed execution state"}),". The plan is provisional \u2014 what the agent currently intends to do. Committed state represents facts established by completed Activities, accepted external messages, and other durable events. Temporal stores Workflow history as an append-only sequence and uses it to reconstruct Workflow state during replay. An ",(0,i.jsx)(n.code,{children:"ActivityTaskCompleted"})," event contains the serialized Activity result, so a later model decision cannot make that completion disappear."]}),"\n",(0,i.jsxs)(n.p,{children:["That distinction changes the shape of the agent loop. Instead of asking an LLM to generate a complete plan and then blindly executing it, each replanning call should receive the goal, the latest observations, the prior plan revision, ",(0,i.jsx)(n.strong,{children:"and"})," a normalized set of committed effects. The model may abandon remaining steps, but completed steps enter the next prompt as constraints on the current world state:"]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-java",children:"public AgentResult run(Goal goal) {\n    while (!goalSatisfied(goal, committed)) {\n        Plan plan = planner.replan(\n            new PlanningContext(goal, revision, committed));\n\n        for (Action action : plan.readyActions()) {\n            if (alreadySatisfied(action, committed)) {\n                continue;\n            }\n            ActionReceipt receipt = tools.execute(action, action.operationId());\n            committed.add(receipt);\n            if (receipt.requiresReplan()) {\n                break;\n            }\n        }\n        revision++;\n    }\n    return summarize(committed);\n}\n"})}),"\n",(0,i.jsxs)(n.p,{children:["In this shape, ",(0,i.jsx)(n.code,{children:"planner.replan(...)"})," and ",(0,i.jsx)(n.code,{children:"tools.execute(...)"})," are ",(0,i.jsx)(n.strong,{children:"Activities"}),", not arbitrary network calls from Workflow code. That matters because Workflow code must remain replay-safe, while non-deterministic operations such as LLM invocations belong behind durable boundaries. Temporal records Activity results in history and returns those recorded results during replay instead of re-running the external call."]}),"\n",(0,i.jsx)(n.h2,{id:"replanning-should-consume-effects-not-merely-step-status",children:"Replanning should consume effects, not merely step status"}),"\n",(0,i.jsxs)(n.p,{children:["A boolean such as ",(0,i.jsx)(n.code,{children:"completed=true"})," is usually too weak for reconciliation. A completed tool call should return an ",(0,i.jsx)(n.strong,{children:"execution receipt"}),' describing the externally relevant postcondition: resource identifiers, amounts, versions, timestamps when materially relevant, and whether a compensating operation exists. The agent then reasons from effects rather than from labels like "step three succeeded."']}),"\n",(0,i.jsx)(n.p,{children:"Consider a reservation agent that initially plans to reserve inventory, create a shipment, and notify a customer. Inventory reservation succeeds, but shipment creation reports a destination restriction. A revised plan must not schedule another reservation merely because the original plan was discarded. The durable input to replanning should state that a specific reservation already exists and identify it. The next plan might change the shipping method, release the reservation, or escalate for approval \u2014 but it should not pretend the reservation never happened."}),"\n",(0,i.jsx)(n.h2,{id:"two-guards-planning-epochs-and-stable-operation-identity",children:"Two guards: planning epochs and stable operation identity"}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Planning epoch."})," External input can arrive while a planning Activity is outstanding; Temporal schedules Workflow Tasks when Signals or Updates arrive, and those messages can mutate durable Workflow state. A plan generated from revision 12 should therefore not be committed blindly if the state has advanced to revision 13 before the planner returns. The planner result carries the revision it used as input, and the Workflow discards stale output and requests a fresh plan \u2014 optimistic concurrency control applied to agent reasoning rather than database rows."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Stable operation identity."})," Retries make stable identity equally important. Temporal recommends idempotent Activities because Activities can be retried; its documentation specifically notes that idempotency keys are appropriate for critical side effects. A plan revision must therefore not double as an operation identity: a reservation that remains semantically the same across replans retains the same business operation key, while a genuinely new reservation receives a new key."]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-java",children:"public ReservationReceipt reserve(ReservationCommand command) {\n    return inventory.reserve(\n        command.sku(),\n        command.quantity(),\n        command.operationId());   // passed through to a downstream API that enforces idempotency\n}\n"})}),"\n",(0,i.jsx)(n.p,{children:"The receipt returned to the Workflow becomes durable evidence of the reservation. This also prevents a subtle failure mode in which a model repeats a tool call after losing conversational context even though the Workflow already possesses proof of the earlier effect."}),"\n",(0,i.jsx)(n.h2,{id:"cancellation-and-compensation-are-forward-actions",children:"Cancellation and compensation are forward actions"}),"\n",(0,i.jsxs)(n.p,{children:['A changed plan often creates pressure to "cancel the old step," but cancellation has a precise boundary: it can stop work that is still ',(0,i.jsx)(n.strong,{children:"in flight"}),"; it cannot retroactively cancel an Activity that has already completed. For long-running Activities, Temporal delivers cancellation cooperatively through Activity heartbeats, so heartbeat configuration determines how promptly an Activity can observe a cancellation request."]}),"\n",(0,i.jsxs)(n.p,{children:["Once an effect has committed, reconciliation becomes a domain operation. If the effect is reversible, ",(0,i.jsx)(n.strong,{children:"compensation"})," is normally the correct mechanism \u2014 the Saga pattern: a sequence of local operations paired with compensating actions, typically executed in reverse order when later work makes earlier effects undesirable. The important semantic point is that compensation creates ",(0,i.jsx)(n.em,{children:"new"})," history; it does not rewrite old history. A released reservation follows a created reservation; a refund follows a charge; a revocation follows a grant:"]}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-java",children:"private void reconcile(Plan revisedPlan) {\n    for (ActionReceipt receipt : compensationsInReverseOrder(revisedPlan, committed)) {\n        ActionReceipt reversal = tools.compensate(receipt);\n        committed.add(reversal);\n    }\n}\n"})}),"\n",(0,i.jsxs)(n.p,{children:["Not every action has a true inverse. An email cannot be unsent, an external party may already have observed a published event, and a physical operation may have crossed an irreversible boundary. Such effects should be modeled as ",(0,i.jsx)(n.strong,{children:"facts that constrain future planning"}),", not as failures of rollback. The revised plan can issue a correction, create a follow-up notification, or route the case to a human decision \u2014 but the historical effect remains part of the state presented to the agent."]}),"\n",(0,i.jsx)(n.h2,{id:"durable-agents-need-forward-only-semantics",children:"Durable agents need forward-only semantics"}),"\n",(0,i.jsx)(n.p,{children:"Replanning also needs to stay distinct from Workflow code versioning. A model changing its runtime plan is ordinary application behavior: a new planning Activity produces a new durable decision after new evidence arrives. Changing deployed Workflow code is different, because replay must still produce commands compatible with existing Event History \u2014 Temporal provides versioning and patching mechanisms for those code changes. Mixing the two concepts leads to brittle systems in which model variability is handled as deployment variability or, worse, non-deterministic Workflow logic."}),"\n",(0,i.jsx)(n.p,{children:"External corrections fit the same forward-only model: Signals and Updates can change running Workflow state, and accepted messages become durable inputs that trigger another planning turn. For very long-running agents, Continue-As-New creates a fresh Event History while carrying forward explicit application state \u2014 which makes the committed-effect ledger an important part of the continuation payload rather than transient model memory."}),"\n",(0,i.jsx)(n.h2,{id:"the-central-design-rule",children:"The central design rule"}),"\n",(0,i.jsxs)(n.blockquote,{children:["\n",(0,i.jsx)(n.p,{children:"An agent may revise intentions at any time, but durable execution never revises facts."}),"\n"]}),"\n",(0,i.jsx)(n.p,{children:"Completed Activities should be represented as committed effects with stable identities and useful receipts; in-flight work may be canceled cooperatively; reversible effects may be compensated; irreversible effects must constrain the next decision. Temporal's history then becomes more than a recovery mechanism \u2014 it becomes the authoritative boundary between what the agent merely planned and what the surrounding world has already observed. That boundary allows adaptive AI behavior without sacrificing replay safety, idempotency, auditability, or operational correctness."}),"\n",(0,i.jsx)(n.h2,{id:"related-notes",children:"Related notes"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.a,{href:"/kb/how-to/aimachinelearning/agentarchitecture/howto-build-effectively-once-agent-workflows",children:"Building Effectively-Once Agent Workflows"})," \u2014 idempotency keys and resume semantics for agent workflows"]}),"\n",(0,i.jsx)(n.li,{children:(0,i.jsx)(n.a,{href:"/kb/explanations/aimachinelearning/agentarchitecture/explanation-progressive-disclosure-on-demand-skills",children:"Progressive Disclosure for AI Agents: On-Demand Skills Instead of Giant Prompts"})}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"references",children:"References"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:(0,i.jsx)(n.a,{href:"https://dzone.com/articles/agent-plan-temporal-activities",children:"The Agent Changed Its Plan Mid-Run: Reconciling AI Decisions With Completed Temporal Activities (DZone)"})}),"\n",(0,i.jsx)(n.li,{children:(0,i.jsx)(n.a,{href:"https://temporal.io/",children:"Temporal \u2014 durable execution and the Saga pattern"})}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>o});var a=t(6540);let i={},s=a.createContext(i);function r(e){let n=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),a.createElement(s.Provider,{value:n},e.children)}}}]);